// Source R23 SVG/PCM assets, with a solid blue location pin for r18.
using System;
namespace Ashfall.Integration.Playable.Input
{
    internal static class R23TeamMarksAssets
    {
        public static byte[] Icon(int index){return Convert.FromBase64String(Icons[index]);}
        public static float[] PingSamples(){byte[] pcm=Convert.FromBase64String(Pcm);var samples=new float[pcm.Length/2];for(int i=0;i<samples.Length;i++)samples[i]=(short)(pcm[i*2]|pcm[i*2+1]<<8)/32768f;return samples;}
        static readonly string[] Icons={
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            ""
        };
        const string Pcm="";
    }
}
